-- V11 MIGRACION: DEPURACION Y SINCRONIZACION DE PERFILES DE CARGO
SET FOREIGN_KEY_CHECKS = 0;

ALTER TABLE clinova_db.perfiles_cargo ADD COLUMN IF NOT EXISTS jefe_inmediato VARCHAR(255);
ALTER TABLE clinova_db.perfiles_cargo ADD COLUMN IF NOT EXISTS version VARCHAR(50) DEFAULT '1';
ALTER TABLE clinova_db.perfiles_cargo ADD COLUMN IF NOT EXISTS fecha VARCHAR(100);
ALTER TABLE clinova_db.perfiles_cargo ADD COLUMN IF NOT EXISTS requisitos_formacion LONGTEXT;
ALTER TABLE clinova_db.perfiles_cargo ADD COLUMN IF NOT EXISTS requisitos_habilidades LONGTEXT;
ALTER TABLE clinova_db.perfiles_cargo ADD COLUMN IF NOT EXISTS versiones LONGTEXT;

-- Asegurar que los cargos existan y sincronizar Medico General
INSERT INTO clinova_db.cargos (id, nombre, area_semaforizacion) VALUES (2, 'Médico general', 'ASISTENCIAL') ON DUPLICATE KEY UPDATE nombre='Médico general';


INSERT INTO clinova_db.perfiles_cargo (cargo_id, jefe_inmediato, version, fecha, mision, responsabilidades, requisitos_educacion, requisitos_formacion, requisitos_habilidades, requisitos_experiencia, versiones, estado)
SELECT id, 'Coordinador de atención Domiciliaria', '2', 'Enero 13-2026', 'Brindar atención médica integral, oportuna, pertinente y de alta calidad a los pacientes tanto en modalidad domiciliaria como en telexperticia e intramural.', '{"ASISTENCIALES": ["Valoracion del paciente inicial o seguimiento: Anamnesis. Examen físico completo. Analisis del estado general del paciente. Establecer un plan de manejo según el estado actual del paciente.", "Orientación y asesoramiento tanto al usuario/a como a la familia y/o cuidadores, actuando, siempre, bajo la más estricta ética profesional.", "Brindar recomendaciones y signos de alarma al paciente, familia y al cuidador.", "Asegurar que durante la prestación del servicio se mantenga una adecuada relación médicopaciente, cordial mediante un trato humanizado.", "Actividades de Promoción de la Salud y Prevención de la enfermedad.", "Prescribir y/o realizar procedimientos para ayudar en el diagnóstico en el manejo de los pacientes según el criterio médico.", "Colaborar en la institución tanto en el ámbito intra como extramural, procurando siempre la excelente calidad y oportunidad en el servicio.", "Diagnosticar y prescribir el tratamiento que debe seguir aplicando los derechos del enfermo.", "Diligenciar los documentos exigidos para el desarrollo de las actividades en el servicio de manera clara, completa y oportuna de conformidad con los procedimientos establecidos.", "Asistir a interconsulta y remitir pacientes a médicos especialistas cuando se requiera y de acuerdo con la norma del sistema de referencia y contrarefenecia.", "Atender la vigilancia epidemiológica en todas aquellas situaciones que sean factor de riegos para la población.", "Colaborar en la elaboración e implantación del plan de emergencia para ser aplicado en la institución.", "Participar en la evaluación de las actividades e impacto de la prestación de los servicios de salud.", "Establecer y mantener las relaciones de coordinación necesarias para lograr una eficaz prestación de los servicios de salud.", "Velar por la consecución oportuna de los recursos necesarios y por la racional utilización de los disponibles y demás bienes a su cargo.", "Actuar con ética médica y de acuerdo al reglamento interno de la institución."], "TELEXPERTICIA": ["Brindar apoyo clínico especializado a otros profesionales de la salud mediante telexperticia sincrónica o asincrónica, de acuerdo con protocolos institucionales.", "Analizar información clínica del paciente (historia clínica, exámenes diagnósticos, imágenes y registros médicos) remitida por el profesional solicitante.", "Emitir conceptos médicos, recomendaciones diagnósticas y terapéuticas, sin reemplazar la atención presencial cuando esta sea requerida.", "Orientar la toma de decisiones clínicas en casos de baja y mediana complejidad dentro de su ámbito de competencia.", "Apoyar la continuidad del cuidado del paciente, garantizando coherencia con guías clínicas y rutas de atención."], "DOMICILIARIOS": ["Realizar valoración clínica integral del paciente en el domicilio, considerando antecedentes personales, familiares, entorno social y condiciones de vivienda.", "Diagnosticar, tratar y hacer seguimiento a patologías agudas y crónicas de baja y mediana complejidad.", "Ejecutar examen físico completo y evaluación funcional según condición clínica del paciente.", "Brindar atención médica con enfoque biopsicosocial, humanizado y centrado en el paciente y su familia.", "Formular medicamentos conforme a guías de práctica clínica y protocolos institucionales.", "Solicitar, interpretar y hacer seguimiento a exámenes diagnósticos y ayudas complementarias.", "Realizar procedimientos médicos básicos permitidos en atención domiciliaria, según competencias y habilitación del servicio.", "Monitorear la evolución clínica del paciente y ajustar el plan de manejo según respuesta terapéutica."], "ADMINISTRATIVOS": ["Colaborar en el control de materiales y equipos para reportar la pérdida y los daños de los mismos.", "Manejar con idoneidad los equipos y materiales para la atención del usuario.", "Elaborar y presentar los informes y registros que le corresponden.", "Asistir a las reuniones programadas por su jefe inmediato superior.", "Reportar daños, pérdidas y necesidades de suministros y materiales médicos.", "Asistir a la jornada de capacitación en servicio."], "DE CALIDAD": ["Ejercer el cargo cumpliendo con la Política y Objetivos del SIG.", "Informar las novedades y cambios de los métodos y normatividad para la actualización de la documentación.", "Participar en las actividades del SIG."], "DE APOYO": ["Otras tareas a fin a su responsabilidad en el puesto y semejantes a las anteriormente descritas, que le sean encomendadas y resulten necesarias por razones del servicio."], "SST": ["Procurar el cuidado integral de su salud (Decreto 1072 de 2015 art. 2.2.4.6.10).", "Suministrar información clara, veraz y completa sobre su estado de salud.", "Cumplir las normas, reglamentos e instrucciones del Sistema de Gestión de la Seguridad y Salud en el Trabajo de la empresa.", "Informar oportunamente al empleador o contratante acerca de los peligros y riesgos latentes en su sitio de trabajo.", "Participar en las actividades de capacitación en seguridad y salud en el trabajo definido en el plan de capacitación del SG-SST.", "Participar y contribuir al cumplimiento de los objetivos del Sistema de Gestión de la Seguridad y Salud en el Trabajo SG-SST.", "Asistir a las evaluaciones médicas ocupacionales programadas por el empleador (Resolución 1843 de 2025 art. 7).", "Acatar las recomendaciones médico-laborales emitidas por el médico especialista en medicina del trabajo, salud ocupacional o seguridad y salud en el trabajo."]}', '{"nivel": "Profesional", "titulo": "Médico", "puntaje": 15, "minimo": 15}', '{"minimo": 8, "items": [{"programa": "Soporte Vital Avanzado (SVA-ACLS)", "puntaje": 2}, {"programa": "Cuidado del Donante", "puntaje": 2}, {"programa": "Atención Integral de Victimas de violencia sexual", "puntaje": 2}, {"programa": "Atención Integral a Victimas de Ataques con Agentes Químicos", "puntaje": 2}, {"programa": "Curso de Acompañamiento en Proceso de Duelo", "puntaje": 2}]}', '{"minimo": 0, "items": [{"habilidad": "Comunicación Asertiva y Trato Humanizado", "puntaje": 5}, {"habilidad": "Toma de Decisiones Clínicas", "puntaje": 5}, {"habilidad": "Trabajo en Equipo Multidisciplinario", "puntaje": 5}]}', '{"cargo": "Médico General", "duracion": "Mínimo un año", "puntaje": 15, "minimo": 40}', '[{"version": "Versión 1", "fecha": "2023-01-15", "descripcion": "Creación inicial del perfil en Kawak"}, {"version": "Versión 2", "fecha": "2026-01-13", "descripcion": "Actualización de funciones asistenciales, telexperticia y SST según normatividad 2026"}]', 'ACTIVO'
FROM clinova_db.cargos WHERE nombre LIKE '%dico general%' OR nombre LIKE '%dico General%' LIMIT 1
ON DUPLICATE KEY UPDATE 
    jefe_inmediato=VALUES(jefe_inmediato),
    version=VALUES(version),
    fecha=VALUES(fecha),
    mision=VALUES(mision),
    responsabilidades=VALUES(responsabilidades),
    requisitos_educacion=VALUES(requisitos_educacion),
    requisitos_formacion=VALUES(requisitos_formacion),
    requisitos_habilidades=VALUES(requisitos_habilidades),
    requisitos_experiencia=VALUES(requisitos_experiencia),
    versiones=VALUES(versiones),
    estado='ACTIVO';
